input.old_string:
body {
  /* 배경: 연한 회색 계열 */
  background-color: #f2f4f6;
  /* 시스템 기본 글꼴 사용 (외부 폰트 파일 사용 안 함) */
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Malgun Gothic",
    "맑은 고딕", sans-serif;
  color: #222;
  line-height: 1.6;
  /* 모바일에서 자동 글자 크기 조정 방지 */
  -webkit-text-size-adjust: 100%;
}

input.new_string:
/* 모바일에서 가로 스크롤이 생기지 않도록 방지 */
html, body {
  width: 100%;
  overflow-x: hidden;
}

body {
  /* 배경: 연한 회색 계열 */
  background-color: #f2f4f6;
  /* 시스템 기본 글꼴 사용 (외부 폰트 파일 사용 안 함) */
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Malgun Gothic",
    "맑은 고딕", sans-serif;
  color: #222;
  line-height: 1.6;
  /* 모바일에서 자동 글자 크기 조정 방지 */
  -webkit-text-size-adjust: 100%;
  /* 긴 매장명/주소가 화면 밖으로 넘치지 않고 자동 줄바꿈되도록 */
  word-break: break-word;
  overflow-wrap: break-word;
}
